  var maxWaitTime = 5000; // Maximum 5 seconds
  var startTime = Date.now();

  // Function to dispatch flash message alerts
  function dispatchFlashAlerts() {
    if (dispatched) return;
    dispatched = true;


      window.dispatchEvent(new CustomEvent('show-alert', {
        detail: { type: 'success', message: "Signed in successfully.", autoDismiss: false }
      }));



  }

  // Listen for the alert system ready event
  function waitForAlertSystem() {
    window.addEventListener('alert-system-ready', function() {
      dispatchFlashAlerts();
    }, { once: true });

    // Fallback: if we don't get the ready signal within maxWaitTime, dispatch anyway
    setTimeout(function() {
      if (!dispatched) {
        dispatchFlashAlerts();
      }
    }, maxWaitTime);
  }

  // Start waiting for the alert system
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', waitForAlertSystem);
  } else {
    waitForAlertSystem();
  }
})();

